class Solution {
  public int countElements(int[] nums, int k) {
    int n = nums.length;
    int[] a = nums.clone();
    java.util.Arrays.sort(a);
    int count = 0;
    for (int i = 0; i < n; ) {
      int j = i;
      while (j < n && a[j] == a[i]) j++;
      if (n - j >= k) count += j - i;
      i = j;
    }
    return count;
  }
}
